use vstd::prelude::*;

verus! {
    /// Extract the j-th column of an n×m matrix `input`.
    /// We require that `input.len() == _n` and each row has length ≥ j+1.
    fn get_column(input: &Vec<Vec<i8>>, _m: usize, _n: usize, j: usize)
        -> (col_out: Vec<i8>)
        requires
            input.len() == _n,
            forall|i: usize| i < _n ==> j < input[i].len(),
        ensures
            col_out.len() == _n,
            forall|i: usize| i < _n ==> col_out[i] == input[i][j],
    {
        let mut col = Vec::with_capacity(_n);
        for i in 0.._n
            invariant
                i <= _n,
                col.len() == i,
                forall|k: usize| k < col.len() ==> col[k] == input[k][j],
            decreases
                _n - i,
        {
            col.push(input[i][j]);
        }
        col
    }

    /// Transpose an n×m matrix into an m×n matrix.
    /// We require `input.len() == n` and each row of `input` has length exactly m.
    fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize)
        -> (result_out: Vec<Vec<i8>>)
        requires
            input.len() == n,
            forall|i: usize| i < n ==> input[i].len() == m,
        ensures
            result_out.len() == m,
            forall|j: usize| j < m ==>
                result_out[j].len() == n
                && forall|i: usize| i < n ==> result_out[j][i] == input[i][j],
    {
        let mut result = Vec::with_capacity(m);
        for j in 0..m
            invariant
                j <= m,
                result.len() == j,
                forall|k: usize| k < j ==>
                    result[k].len() == n
                    && forall|i: usize| i < n ==> result[k][i] == input[i][k],
            decreases
                m - j,
        {
            // the call satisfies get_column’s requires:
            //   input.len() == n, row‐lengths == m ⇒ j < m ⇒ j < input[i].len()
            let col = get_column(&input, m, n, j);
            result.push(col);
        }
        result
    }
} // end verus!

fn main() {
    let mat = vec![
        vec![1, 2, 3],
        vec![4, 5, 6],
    ]; // 2×3 matrix

    let t = column_stack(mat, 3, 2);
    // t should be a 3×2 matrix: [[1,4],[2,5],[3,6]]
    assert_eq!(t, vec![
        vec![1, 4],
        vec![2, 5],
        vec![3, 6],
    ]);

    println!("Transpose computed successfully: {:?}", t);
}